/**
 * Real door responses for tests. Use these instead of hand-made shapes: a
 * fake that drifts from the door (a `posts` page, a `body`, a `role` on an
 * item) is how the Dev 38 crash got past jest.
 *
 * door.json: generated by running the runtime's door.js (see
 * scripts/communities/generateDoorFixtures.mjs, and `$source` in the file for
 * the commit). dev-runtime-2026-10-30.json: the
 * real Dev runtime's responses, captured 2026-10-30, identities anonymised.
 *
 * Both are typed against the door contract with `satisfies`, so a fixture
 * that stops matching the contract fails tsc. Every getter returns a fresh
 * copy, so a test can change what it gets without touching other tests.
 */
import {type Community} from '#/lib/agent-runtime/communitiesClient'
import {
  type DoorAgentGrant,
  type DoorAgentSponsor,
  type DoorCommunity,
  type DoorCommunityList,
  type DoorCommunityResponse,
  type DoorExport,
  type DoorItem,
  type DoorItemResponse,
  type DoorJoinInfo,
  type DoorRoster,
  type DoorTimelinePage,
} from '#/lib/communities/doorContract'
import DEV_JSON from './dev-runtime-2026-10-30.json'
import DOOR_JSON from './door.json'

export const DOOR = DOOR_JSON satisfies {
  $source: {commit: string}
  list: DoorCommunityList
  listAsMember: DoorCommunityList
  community: DoorCommunityResponse
  joinInfo: DoorJoinInfo
  post: DoorItemResponse
  reply: DoorItemResponse
  timeline: DoorTimelinePage
  export: DoorExport
  roster: DoorRoster
  grant: DoorAgentGrant
  communityWithSponsorMember: DoorCommunityResponse
}

export const DEV_RUNTIME = DEV_JSON satisfies {
  list: DoorCommunityList
  home: DoorCommunityResponse
  timeline: DoorTimelinePage
  joininfo: DoorJoinInfo
  grant: DoorAgentGrant
  roster: DoorRoster
}

/** The runtime commit door.json was generated from. */
export const DOOR_SOURCE_COMMIT = DOOR.$source.commit

/** The configured agent DID in door.json (a fake). */
export const DOOR_AGENT_DID = (DOOR.community.community.agent as {did: string})
  .did

const copy = <T>(v: T): T => JSON.parse(JSON.stringify(v)) as T

/** A timeline page: 4 items, newest first, cursor null. */
export function doorTimeline(): DoorTimelinePage {
  return copy(DOOR.timeline as DoorTimelinePage)
}

/** The configured agent sponsor DID in door.json (a fake). */
export const DOOR_SPONSOR_DID = (
  DOOR.community.community.agentSponsor as DoorAgentSponsor
).did

/**
 * The community (`GET /:id`), as the signed-in admin sees it. The sponsor
 * holds no membership here, so `agentSponsor.handle` is null.
 */
export function doorCommunity(): DoorCommunity {
  return copy(DOOR.community.community as DoorCommunity)
}

/**
 * The same community after the sponsor joined, as a member (not an admin)
 * sees it: `agentSponsor.handle` is the sponsor's member id.
 */
export function doorCommunityWithSponsorMember(): DoorCommunity {
  return copy(DOOR.communityWithSponsorMember.community as DoorCommunity)
}

/**
 * One timeline item:
 *   post   - a member's top-level post (author DID stored)
 *   reply  - a member's reply to `post`
 *   agent  - the configured agent's reply to `post`, with sources
 *   legacy - an older member post with no stored author DID (did: null)
 */
export function doorItem(
  kind: 'post' | 'reply' | 'agent' | 'legacy',
): DoorItem {
  const items = doorTimeline().items
  const find = (pred: (i: DoorItem) => boolean) => {
    const found = items.find(pred)
    if (!found) throw new Error(`door.json has no ${kind} item`)
    return found
  }
  switch (kind) {
    case 'post':
      return find(i => i.id === DOOR.post.item.id)
    case 'reply':
      return find(i => i.id === DOOR.reply.item.id)
    case 'agent':
      return find(i => i.author?.is_agent === true)
    case 'legacy':
      return find(i => i.author?.did === null)
  }
}

/** One page of `items` with the door's page shape. */
export function doorPage(
  items: DoorItem[],
  cursor: string | null = null,
): DoorTimelinePage {
  return {items: copy(items), cursor}
}

/**
 * A door community as communitiesClient hands it to the app: the door's own
 * fields, with `viewer_is_admin` read into `viewerIsAdmin` (readCommunity).
 */
export function asClientCommunity(c: DoorCommunity): Community {
  const {viewer_is_admin, ...rest} = copy(c)
  return viewer_is_admin === undefined
    ? rest
    : {...rest, viewerIsAdmin: viewer_is_admin}
}

/**
 * A community as communitiesClient returns it (`viewer_is_admin` read into
 * `viewerIsAdmin`), built from door.json's community. By default it is what
 * the door answers for a config with only a name and every agent/admin flag
 * off: no description, accent or wording version, and no `agent`,
 * `agentSponsor` or `viewer_is_admin` key. `overrides` sets fields on top.
 */
export function clientCommunity(
  overrides: Partial<Community> & Record<string, unknown> = {},
): Community {
  const {
    agent: _agent,
    agent_error: _agentError,
    agentSponsor: _agentSponsor,
    viewer_is_admin: _admin,
    ...base
  } = doorCommunity()
  return {
    ...base,
    description: null,
    accent: null,
    wording_version: null,
    ...overrides,
  }
}
